<div class="ff-data-picker" x-show="libraryTab==='data'" x-cloak>
<p class="ff-muted" x-text="pickerSlot?@js(__('filaforge::studio.picker_connect_hint')):@js(__('filaforge::studio.picker_hint'))"></p>
<label class="ff-picker-search"><span class="ff-heading-icon" aria-hidden="true" x-html="iconSvg('magnifying-glass')"></span><input x-ref="dataPickerSearch" type="search" x-model="pickerQuery" placeholder="{{ __('filaforge::studio.picker_search') }}" aria-label="{{ __('filaforge::studio.picker_search') }}"></label>
<p class="ff-picker-status" role="status" x-show="pickerBusy">{{ __('filaforge::studio.saving') }}</p>
<p class="ff-picker-error" role="alert" x-show="pickerError" x-text="pickerError"></p>
<p class="ff-muted" role="status" x-show="pickerLoading">{{ __('filaforge::studio.picker_loading') }}</p>
<div x-show="!pickerComponent&&!pickerLoading" :aria-busy="pickerBusy">
<template x-if="!pickerSlot"><div class="ff-picker-group" x-show="pickerComponents().length"><h3>{{ __('filaforge::studio.picker_tools') }}</h3><template x-for="component in pickerComponents()" :key="component.name"><button type="button" class="ff-picker-option" :disabled="pickerBusy" x-on:click="chooseDataComponent(component)"><span class="ff-heading-icon" aria-hidden="true" x-html="iconSvg('layer-group')"></span><span x-text="component.label"></span><span class="ff-picker-plus" aria-hidden="true" x-html="iconSvg('plus')"></span></button></template></div></template>
<template x-if="!pickerReplace"><div><template x-for="source in pickerSources()" :key="source.name"><div class="ff-picker-group"><h3 x-text="source.label"></h3><template x-for="[field,definition] in source.fields" :key="field"><button type="button" class="ff-picker-option" :disabled="pickerBusy" x-on:click="chooseDataField(source.name,field)"><span class="ff-heading-icon" aria-hidden="true" x-html="iconSvg(definition.type==='image'?'image':definition.type==='url'?'link':'database')"></span><span x-text="definition.label||field"></span><span class="ff-picker-plus" aria-hidden="true" x-html="iconSvg(pickerSlot?'link':'plus')"></span></button></template></div></template></div></template>
<p class="ff-muted" x-show="!pickerComponents().length&&!pickerSources().length">{{ __('filaforge::studio.picker_empty') }}</p>
</div>
<template x-if="pickerComponent"><div class="ff-picker-form"><button type="button" class="ff-source-link" x-on:click="pickerComponent=null;pickerError=''">{{ __('filaforge::studio.picker_back') }}</button><h3 x-text="pickerComponent.label"></h3><template x-for="key in pickerComponent.arguments" :key="key"><label class="ff-source-field"><span x-text="key"></span><input type="text" x-model="pickerArguments[key]" maxlength="1000"></label></template><button type="button" class="ff-btn ff-primary ff-picker-launch" :disabled="pickerBusy" x-on:click="addPickerElement('component','',pickerComponent.name)">{{ __('filaforge::studio.picker_add_page') }}</button></div></template>
<button type="button" class="ff-source-link ff-picker-reset" x-show="pickerSlot||pickerReplace" x-on:click="openDataPicker()">{{ __('filaforge::studio.picker_back') }}</button>
<button type="button" class="ff-btn ff-picker-launch" x-show="pickerError&&!pickerLoading" x-on:click="loadDataCatalog()">{{ __('filaforge::studio.picker_retry') }}</button>
</div>
